const { useLayoutEffect, useRef, useState } = React;

const LONG_TEXT = "field-sizing 让输入框跟着内容一起变宽";
const MODES = ["fixed", "content"];

const STYLE = `
  @scope {
    .cb-range { accent-color: var(--tau-accent); }
  }
`;

const Chip = ({ children }) => (
  <code className="rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-sm text-ink-2">{children}</code>
);

const Readout = ({ rows }) => (
  <dl className="m-0 grid grid-cols-[auto_minmax(0,1fr)] gap-x-4 gap-y-1.5 rounded-tau-md bg-hover px-3 py-2.5">
    {rows.map(([label, value]) => (
      <React.Fragment key={label}>
        <dt className="text-tau-sm text-ink-3">{label}</dt>
        <dd className="m-0 truncate font-tau-mono text-tau-sm text-ink-1">{value}</dd>
      </React.Fragment>
    ))}
  </dl>
);

const Component = () => {
  const inputRef = useRef(null);
  const [mode, setMode] = useState("content");
  const [maxWidth, setMaxWidth] = useState(320);
  const [text, setText] = useState("");
  const [size, setSize] = useState({ box: 0, content: 0 });

  // 每次内容或约束变化后同步读出框宽与内容宽，二者之差就是需要横向滚动的部分
  useLayoutEffect(() => {
    const input = inputRef.current;
    const measure = () => setSize({ box: input.clientWidth, content: input.scrollWidth });
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(input);
    return () => observer.disconnect();
  }, [mode, maxWidth, text]);

  const overflow = Math.max(0, size.content - size.box);

  return (
    <div className="@container flex flex-col gap-3">
      <style>{STYLE}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
        <div className="relative flex min-h-[140px] min-w-0 flex-col justify-center gap-2 overflow-hidden rounded-tau-md border border-line-1 p-4">
          <div
            className="pointer-events-none absolute inset-y-3 border-l border-dashed border-accent"
            style={{ left: `min(calc(1rem + ${maxWidth}px), calc(100% - 1rem))` }}
          >
            <span className="absolute top-0 left-1 whitespace-nowrap font-tau-mono text-tau-tiny text-accent-text">max-width</span>
          </div>
          <input
            ref={inputRef}
            type="text"
            value={text}
            onChange={event => setText(event.target.value)}
            placeholder="输入试试，空时按占位文字定宽"
            className={`h-9 rounded-tau-sm border border-line-1 bg-surface px-2.5 text-tau-body text-ink-1 outline-none transition-colors placeholder:text-ink-3 focus:border-accent ${
              mode === "content" ? "field-sizing-content" : "field-sizing-fixed"
            }`}
            style={{ minWidth: "6ch", maxWidth: `min(${maxWidth}px, 100%)` }}
          />
          <span className="text-tau-sm text-ink-3">
            {overflow > 0 ? `超出 ${overflow}px，内容在框内横向滚动` : "内容完整可见"}
          </span>
        </div>
        <div className="flex min-w-0 flex-col gap-3">
          <ui.RadioGroup label="field-sizing" value={mode} onValueChange={setMode} orientation="horizontal">
            {MODES.map(value => (
              <ui.Radio key={value} value={value} label={value} />
            ))}
          </ui.RadioGroup>
          <label className="flex items-center gap-3">
            <span className="shrink-0 font-tau-mono text-tau-sm text-ink-2">max-width</span>
            <input
              type="range"
              min={120}
              max={480}
              step={10}
              value={maxWidth}
              onChange={event => setMaxWidth(Number(event.target.value))}
              className="cb-range h-1.5 min-w-0 flex-1 cursor-pointer"
            />
            <span className="w-14 shrink-0 text-right font-tau-mono text-tau-sm text-ink-1">{maxWidth}px</span>
          </label>
          <Readout
            rows={[
              ["字符数", text.length],
              ["框宽", `${size.box}px`],
              ["内容宽", `${size.content}px`],
            ]}
          />
        </div>
      </div>
      <div className="flex flex-wrap items-center gap-2">
        <ui.Button variant="secondary" size="sm" icon={icons.TextCursorInput} onClick={() => setText(LONG_TEXT)}>
          填入长文本
        </ui.Button>
        <ui.Button variant="ghost" size="sm" icon={icons.RotateCcw} onClick={() => setText("")}>
          清空
        </ui.Button>
        <span className="ml-auto text-tau-sm text-ink-3">
          当前 <Chip>field-sizing: {mode}</Chip>
        </span>
      </div>
    </div>
  );
};

const { useLayoutEffect, useRef, useState } = React;

const SAMPLE = ["第一行", "第二行", "第三行", "第四行：超过 rows 了", "第五行", "第六行", "第七行"].join("\n");
const MODES = ["fixed", "content"];

const STYLE = `
  @scope {
    .cb-range { accent-color: var(--tau-accent); }
  }
`;

const Slider = ({ label, value, min, max, onChange, unit }) => (
  <label className="flex items-center gap-3">
    <span className="w-20 shrink-0 font-tau-mono text-tau-sm text-ink-2">{label}</span>
    <input
      type="range"
      min={min}
      max={max}
      value={value}
      onChange={event => onChange(Number(event.target.value))}
      className="cb-range h-1.5 min-w-0 flex-1 cursor-pointer"
    />
    <span className="w-12 shrink-0 text-right font-tau-mono text-tau-sm text-ink-1">
      {value}
      {unit}
    </span>
  </label>
);

const Readout = ({ rows }) => (
  <dl className="m-0 grid grid-cols-[auto_minmax(0,1fr)] gap-x-4 gap-y-1.5 rounded-tau-md bg-hover px-3 py-2.5">
    {rows.map(([label, value]) => (
      <React.Fragment key={label}>
        <dt className="text-tau-sm text-ink-3">{label}</dt>
        <dd className="m-0 truncate font-tau-mono text-tau-sm text-ink-1">{value}</dd>
      </React.Fragment>
    ))}
  </dl>
);

const Component = () => {
  const areaRef = useRef(null);
  const [mode, setMode] = useState("content");
  const [rows, setRows] = useState(3);
  const [maxLines, setMaxLines] = useState(6);
  const [text, setText] = useState("");
  const [size, setSize] = useState({ box: 0, content: 0 });

  useLayoutEffect(() => {
    const area = areaRef.current;
    const measure = () => setSize({ box: area.clientHeight, content: area.scrollHeight });
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(area);
    return () => observer.disconnect();
  }, [mode, rows, maxLines, text]);

  const lines = text ? text.split("\n").length : 0;
  const scrolling = size.content - size.box > 1;

  return (
    <div className="@container flex flex-col gap-3">
      <style>{STYLE}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
        <div className="flex min-h-[180px] min-w-0 flex-col justify-center gap-2 rounded-tau-md border border-line-1 p-4">
          <textarea
            ref={areaRef}
            rows={rows}
            value={text}
            onChange={event => setText(event.target.value)}
            placeholder={"多输入几行试试\n按回车换行"}
            className={`w-full resize-none rounded-tau-sm border border-line-1 bg-surface px-2.5 py-2 text-tau-body leading-[1.6] text-ink-1 outline-none transition-colors placeholder:text-ink-3 focus:border-accent ${
              mode === "content" ? "field-sizing-content" : "field-sizing-fixed"
            }`}
            style={{ maxHeight: `calc(${maxLines}lh + 1rem + 2px)` }}
          />
          <span className="text-tau-sm text-ink-3">
            {scrolling ? "内容超出，出现滚动条" : mode === "content" ? "高度跟随内容，rows 不再起作用" : `高度由 rows="${rows}" 决定`}
          </span>
        </div>
        <div className="flex min-w-0 flex-col gap-3">
          <ui.RadioGroup label="field-sizing" value={mode} onValueChange={setMode} orientation="horizontal">
            {MODES.map(value => (
              <ui.Radio key={value} value={value} label={value} />
            ))}
          </ui.RadioGroup>
          <Slider label="rows" value={rows} min={2} max={6} onChange={setRows} unit="" />
          <Slider label="max-height" value={maxLines} min={3} max={12} onChange={setMaxLines} unit="lh" />
          <Readout
            rows={[
              ["行数", lines],
              ["框高", `${size.box}px`],
              ["内容高", `${size.content}px`],
            ]}
          />
        </div>
      </div>
      <div className="flex flex-wrap items-center gap-2">
        <ui.Button variant="secondary" size="sm" icon={icons.WrapText} onClick={() => setText(SAMPLE)}>
          填入七行
        </ui.Button>
        <ui.Button variant="ghost" size="sm" icon={icons.RotateCcw} onClick={() => setText("")}>
          清空
        </ui.Button>
      </div>
    </div>
  );
};

const { useState } = React;

// 字符串为原文，数组为空格及其答案
const PARAGRAPHS = [
  ["我与父亲不相见已", ["二年余"], "了，我最不能", ["忘记"], "的是他的背影。"],
  ["我看见他", ["戴着"], "黑布小帽，穿着黑布", ["大马褂"], "，深青布", ["棉袍"], "，", ["蹒跚"], "地走到铁道边，慢慢", ["探身"], "下去，尚不大难。"],
  ["可是他穿过铁道，要", ["爬上"], "那边月台，就不容易了。他用两手", ["攀着"], "上面，两脚再向上", ["缩"], "；他肥胖的身子向左微", ["倾"], "，显出努力的样子。"],
  ["这时我看见他的", ["背影"], "，我的", ["泪"], "很快地", ["流下来"], "了。"],
];

// 给每个空格编号，作为输入状态的下标
const ANSWERS = [];
const LAYOUT = PARAGRAPHS.map(parts =>
  parts.map(part => {
    if (typeof part === "string") return part;
    ANSWERS.push(part[0]);
    return ANSWERS.length - 1;
  })
);

const emptyValues = () => ANSWERS.map(() => "");

const BLANK_STATE = {
  idle: "border-accent text-accent-text focus:bg-accent-soft",
  ok: "border-ok text-ok",
  wrong: "border-danger text-danger focus:bg-danger-soft",
};

const Component = () => {
  const [values, setValues] = useState(emptyValues);
  const [checked, setChecked] = useState(false);
  const [contentSizing, setContentSizing] = useState(true);

  const score = values.filter((value, index) => value.trim() === ANSWERS[index]).length;

  const update = (index, value) => {
    setChecked(false);
    setValues(current => current.map((item, i) => (i === index ? value : item)));
  };
  const reveal = () => {
    setValues([...ANSWERS]);
    setChecked(true);
  };
  const reset = () => {
    setValues(emptyValues());
    setChecked(false);
  };

  const stateOf = index => {
    if (!checked) return "idle";
    return values[index].trim() === ANSWERS[index] ? "ok" : "wrong";
  };

  return (
    <div className="flex flex-col gap-3">
      <div className="flex flex-col gap-3 rounded-tau-md border border-line-1 p-4">
        <div className="flex items-baseline justify-between gap-3">
          <span className="text-tau-body text-ink-1">《背影》节选</span>
          <span className="text-tau-sm text-ink-3">朱自清</span>
        </div>
        {LAYOUT.map((parts, paragraphIndex) => (
          <p key={paragraphIndex} className="m-0 text-tau-body leading-[2.2] text-ink-2">
            {parts.map((part, partIndex) =>
              typeof part === "string" ? (
                <span key={partIndex}>{part}</span>
              ) : (
                <input
                  key={partIndex}
                  type="text"
                  aria-label={`第 ${part + 1} 空`}
                  value={values[part]}
                  onChange={event => update(part, event.target.value)}
                  className={`mx-1 rounded-tau-sm border-0 border-b-2 border-dotted bg-transparent px-1 text-center text-tau-body text-ink-1 outline-none transition-colors ${BLANK_STATE[stateOf(part)]} ${
                    contentSizing ? "field-sizing-content" : "field-sizing-fixed"
                  }`}
                  style={{ minWidth: "2.5em" }}
                />
              )
            )}
          </p>
        ))}
      </div>
      <div className="flex flex-wrap items-center gap-2">
        <ui.Button variant="primary" size="sm" icon={icons.ListChecks} onClick={() => setChecked(true)}>
          检查
        </ui.Button>
        <ui.Button variant="secondary" size="sm" icon={icons.Eye} onClick={reveal}>
          显示答案
        </ui.Button>
        <ui.Button variant="ghost" size="sm" icon={icons.RotateCcw} onClick={reset}>
          重置
        </ui.Button>
        {checked && (
          <span
            className={`rounded-full px-2.5 py-0.5 text-tau-meta ${
              score === ANSWERS.length ? "bg-ok-soft text-ok" : "bg-warn-soft text-warn"
            }`}
          >
            答对 {score} / {ANSWERS.length}
          </span>
        )}
        <div className="ml-auto">
          <ui.Switch checked={contentSizing} onCheckedChange={setContentSizing} label="field-sizing: content" size="sm" />
        </div>
      </div>
    </div>
  );
};
